"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(root):
    if (root is None):
        return []
    queue = [root]
    result = []
    while (len(queue) > 0):
        levelSize = len(queue)
        currentLevel = []
        for _ in range(0, levelSize):
            node = queue.pop(0)
            currentLevel.append(node.value)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(currentLevel)
    return result
